(() => {
  const A=window.DEMO,$=s=>document.querySelector(s);let closeCurrent=null;
  function toast(message){let t=$('#toast');if(!t){t=document.createElement('div');t.className='toast';t.id='toast';t.setAttribute('role','status');document.body.append(t);}clearTimeout(t._timer);t.textContent=message;t.style.display='block';t._timer=setTimeout(()=>t.style.display='none',3200);}
  function attempt(fn){try{return fn();}catch(e){toast(e.message);return null;}}
  function dialog(title,body,{wide=false}={}){
    closeCurrent?.();const previous=document.activeElement,bg=document.createElement('div');bg.className='demo-backdrop';bg.innerHTML='<section class="demo-dialog '+(wide?'wide':'')+'" role="dialog" aria-modal="true" aria-label="'+A.esc(title)+'"><header><h2>'+A.esc(title)+'</h2><button class="dialog-x" aria-label="닫기">×</button></header><div class="dialog-content">'+body+'</div></section>';document.body.append(bg);
    const close=()=>{bg.remove();previous?.focus();document.removeEventListener('keydown',keyboard);closeCurrent=null;};
    function keyboard(e){if(e.key==='Escape')close();if(e.key==='Tab'){const focus=[...bg.querySelectorAll('button,a,input,textarea,select')].filter(x=>!x.disabled);const i=focus.indexOf(document.activeElement);if(e.shiftKey&&i<=0){e.preventDefault();focus.at(-1)?.focus();}else if(!e.shiftKey&&i===focus.length-1){e.preventDefault();focus[0]?.focus();}}}
    document.addEventListener('keydown',keyboard);bg.querySelector('.dialog-x').onclick=close;bg.onclick=e=>{if(e.target===bg)close();};closeCurrent=close;bg.querySelector('button').focus();return {el:bg,close};
  }
  function history(id){const s=A.read(),sub=s.submissions.filter(x=>x.taskId===id),ev=A.taskInfo(id).timeline.map(e=>({action:e.label,reason:e.note,at:e.at}));dialog('사진·검토 이력 · ID '+id,'<p class="muted">사진은 제출 순서대로 남으며, 최신 제출을 검토합니다.</p><div class="history-photos">'+sub.map((x,i)=>'<figure><img src="'+A.esc(x.photo)+'" alt="'+x.attempt+'차 제출 사진"><figcaption><b>'+A.esc(x.attempt)+'차 · '+A.esc(A.labels[x.status]||x.status)+'</b><span>'+A.esc(x.at.slice(0,16).replace('T',' '))+'</span><p>'+A.esc(x.report)+'</p><small>'+(i===sub.length-1?'최신 사진 · '+(x.status==='confirmed'?'반영':'검토 대상'):'이력 보관')+'</small></figcaption></figure>').join('')+'</div><div class="history-events">'+ev.map(e=>'<p><small>'+A.esc(e.at.slice(5,16).replace('T',' '))+'</small> <b>'+A.esc(e.action)+'</b> '+A.esc(e.reason)+'</p>').join('')+'</div>',{wide:true});}
  function extensionHTML(id){const e=A.read().extensions[id],t=A.effectiveTasks().find(t=>t.id===id);if(!e||!t)return '<p class="muted">추가 기간 요청이 없습니다.</p>';return '<h3>추가 기간 요청 <span class="pill amber">'+({pending:'검토 대기',approved:'수락 · 지연·이월',rejected:'반려'}[e.state])+'</span></h3><h4>'+A.esc(t.name)+'</h4><div class="id">ID '+id+'</div><div class="dates">기존 종료일<strong>'+e.original.replaceAll('-','.')+'</strong><br>요청 종료일<strong>'+e.end.replaceAll('-','.')+'</strong></div><div class="request-reason">'+A.esc(e.reason)+'</div>'+(e.state==='pending'?'<div class="request-actions"><button class="secondary" data-extension-reject="'+id+'">반려</button><button class="primary" data-extension-accept="'+id+'">수락</button></div>':'<p class="approval-note">'+(e.state==='approved'?'기존 종료일을 보존하고 변경된 일정과 지연·이월 사유를 함께 남겼습니다.':A.esc(e.reviewReason))+'</p>')+'<p class="approval-note">일정 수락은 작업 완료 확인과 구분합니다.</p>';}
  function bindExtension(root,done){root.querySelectorAll('[data-extension-accept]').forEach(b=>b.onclick=()=>attempt(()=>{A.decideExtension(b.dataset.extensionAccept,true);done();badges();toast('추가 기간을 수락했습니다. 원래 일정과 함께 이월합니다.');}));root.querySelectorAll('[data-extension-reject]').forEach(b=>b.onclick=()=>reasonDialog('추가 기간 요청 반려',reason=>{A.decideExtension(b.dataset.extensionReject,false,reason);done();badges();}));}
  function reasonDialog(title,submit){const d=dialog(title,'<form id="demo-reason-form"><label>반려 사유 <span class="required">필수</span><textarea required maxlength="2000" placeholder="현장에서 보완할 내용을 적어 주세요."></textarea></label><div class="demo-actions"><button class="primary">반려 보내기</button></div><p class="form-error" role="alert"></p></form>');d.el.querySelector('form').onsubmit=e=>{e.preventDefault();const v=d.el.querySelector('textarea').value.trim();if(!v){d.el.querySelector('.form-error').textContent='반려 사유를 작성해 주세요.';return;}try{submit(v);d.close();toast('반려 사유를 전달했습니다.');}catch(err){d.el.querySelector('.form-error').textContent=err.message;}};d.el.querySelector('textarea').focus();}
  function badges(){const n=A.counts().site_a;document.querySelectorAll('[data-site-link="site_a"] .badge,.tabs .badge').forEach(e=>e.textContent=n);window.AlohaNavigation?.refresh();}
  function classifyDialog(){const list=A.effectiveTasks();const d=dialog('간트 작업 분류','<p class="muted">벽·바닥·천장은 AI 관측 대상으로, 그 외는 현장 증빙 제출 대상으로 분류합니다. 아래 기본 분류는 확인 후 변경할 수 있습니다.</p><div class="classification-list">'+list.map(t=>'<label><span><small>ID '+t.id+'</small>'+A.esc(t.name)+'</span><select data-category="'+t.id+'">'+Object.entries(A.categories).map(([k,v])=>'<option value="'+k+'" '+(A.category(t)===k?'selected':'')+'>'+v+'</option>').join('')+'</select><small class="route">'+(['WALL','FLOOR','CEILING'].includes(A.category(t))?'AI 관측':'현장 증빙')+'</small></label>').join('')+'</div>',{wide:true});d.el.querySelectorAll('[data-category]').forEach(select=>select.onchange=()=>attempt(()=>{A.classify(select.dataset.category,select.value);select.nextElementSibling.textContent=['WALL','FLOOR','CEILING'].includes(select.value)?'AI 관측':'현장 증빙';toast('작업 분류를 저장했습니다.');}));}
  async function photoFile(file){if(!file||!/^image\/(jpeg|png|webp)$/i.test(file.type))throw Error('JPG, PNG 또는 WebP 사진을 선택해 주세요.');if(file.size>20*1024*1024)throw Error('20MB 이하의 사진을 선택해 주세요.');const bmp=await createImageBitmap(file);try{const scale=Math.min(1,1400/Math.max(bmp.width,bmp.height)),c=document.createElement('canvas');c.width=Math.round(bmp.width*scale);c.height=Math.round(bmp.height*scale);c.getContext('2d').drawImage(bmp,0,0,c.width,c.height);return c.toDataURL('image/jpeg',.82);}finally{bmp.close();}}
  function init(){
    const site_ad=$('.site_ad');const control=document.createElement('div');control.className='demo-controls';control.innerHTML='<span class="demo-mode">프로토타입 · 브라우저 저장</span><a href="02-field-submission.html">현장 제출 ↗</a><button id="demo-reset">시연 초기화</button>';
    if(site_ad){site_ad.lastElementChild?.remove();site_ad.append(control);}else{control.classList.add('mobile-demo');control.querySelector('a').href='01-hq-review.html';control.querySelector('a').textContent='본사 검토 ↗';document.body.prepend(control);}
    $('#demo-reset').onclick=()=>{const d=dialog('시연 내용 초기화','<p>이 브라우저에 저장한 제출 사진과 검토 결과를 지우고 처음 예시로 돌아갑니다.</p><div class="demo-actions"><button class="secondary" id="keep-demo">취소</button><button class="primary" id="confirm-reset">초기화</button></div>');d.el.querySelector('#keep-demo').onclick=d.close;d.el.querySelector('#confirm-reset').onclick=()=>{A.reset();location.href='index.html';};};
    for(const site of A.read().sites){if(document.querySelector('[data-site-link="'+site.id+'"]'))continue;const nav=$('.site-list');if(nav){const a=document.createElement('a');a.className='site';a.dataset.siteLink=site.id;a.href='index.html?site='+encodeURIComponent(site.id);a.innerHTML='<span class="site-name">'+A.esc(site.name)+'<small>'+A.esc(site.city)+'</small></span><span class="site-check">○</span>';nav.append(a);}}
    document.addEventListener('click',e=>{const img=e.target.closest('.photo img,.history-photos img,.evidence-strip img');if(img){dialog(img.alt||'사진 크게 보기','<img class="large-photo" src="'+A.esc(img.src)+'" alt="'+A.esc(img.alt)+'">',{wide:true});}});
    document.addEventListener('keydown',e=>{if(e.key==='Escape'){const r=$('#reject-dialog');if(r)r.style.display='none';const n=$('#new-site-dialog');if(n)n.style.display='none';}});
    badges();
  }
  window.DemoUI={toast,attempt,dialog,history,extensionHTML,bindExtension,reasonDialog,badges,classifyDialog,photoFile};
  document.addEventListener('DOMContentLoaded',init);
})();
